.td-site-container {
  max-width: 1280px;
  margin: 0 auto;
  padding: 0 28px;
}

// Shell pages are full-bleed, so the centered landing container would let the
// brand drift with the viewport. Pin the navbar to the viewport edges instead:
// the logo anchors the top-left corner above the sidebar (matching its 16px
// content inset) and the controls anchor the top-right above the TOC rail.
.td-shell-chrome .td-site-header .td-site-container {
  max-width: none;
  padding-inline: 16px;
}

// Auto-hide is opt-in and applies only on the desktop side of the md
// breakpoint, where a mouse-like pointer can reveal it. Every drawer-width
// viewport keeps the normal sticky navbar visible, regardless of the policy.
.td-navbar-autohide {
  display: contents;
}

@media (min-width: 768px) and (hover: hover) and (pointer: fine) {
  // The hidden navbar keeps its slot. The wrapper stays in normal flow as
  // the sticky band the header always owns, so hiding reclaims nothing,
  // toggling never reflows the page, and content at rest is never covered —
  // the bar fades in place over whatever has scrolled beneath the band.
  .td-navbar-autohide {
    --td-navbar-reveal-inset: 64px;
    --td-navbar-reveal-height: 60%;
    position: sticky;
    inset-block-start: 0;
    z-index: 100;
    display: block;
    height: $td-navbar-min-height;
    // The band itself must not steal clicks from content scrolled beneath
    // it or from collapsed-rail restore controls in the two top corners.
    pointer-events: none;
  }

  // Only the upper 60% of this center strip wakes a hidden navbar. Once
  // revealed, the navbar remains a normal full-width interactive surface.
  .td-navbar-autohide::before {
    content: '';
    position: absolute;
    inset-block-start: 0;
    inset-inline: var(--td-navbar-reveal-inset);
    z-index: 0;
    height: var(--td-navbar-reveal-height);
    pointer-events: auto;
  }

  .td-navbar-autohide > .td-site-header {
    position: absolute;
    inset-block-start: 0;
    inset-inline: 0;
    z-index: 1;
    width: 100%;
    opacity: 0;
    pointer-events: none;
    transition:
      opacity 180ms ease,
      box-shadow 200ms ease;
  }

  .td-navbar-autohide:hover,
  .td-navbar-autohide:focus-within {
    > .td-site-header {
      opacity: 1;
      pointer-events: auto;
    }
  }

  // Hero pages own their navbar treatment: the bar overlays the featured
  // image and scrolls away with it, so the auto-hide band steps aside.
  body.td-shell-chrome--hero > .td-navbar-autohide {
    display: contents;

    &::before {
      content: none;
    }

    > .td-site-header {
      opacity: 1;
      pointer-events: auto;
      transition: none;
    }
  }
}

.td-site-header {
  position: sticky;
  top: 0;
  z-index: 100;
  // Fixed shell rails clear exactly $td-navbar-min-height, and the auto-hide
  // band reserves exactly that much slot. A pinned bar has to occupy the same
  // height, so the rule sits inside the band -- a fixed height under
  // border-box sizing -- rather than adding a pixel below it. Without this a
  // pinned surface starts its article column one pixel under the fixed TOC
  // rail, and the breadcrumb row no longer lines up with the outline heading.
  height: $td-navbar-min-height;
  border-bottom: 1px solid var(--bs-border-color);
  background: var(--td-brand-header-bg);
  transition: box-shadow 200ms ease;
  -webkit-backdrop-filter: blur(8px);
  backdrop-filter: blur(8px);

  &.td-scrolled {
    box-shadow: var(--td-brand-shadow-sm);
  }

  // The container and the row inherit that height, so the controls stay
  // centered in the band the header measures rather than in their own content.
  > .td-site-container {
    height: 100%;
  }

  // Three zones on one grid row: brand at the start, the site's own menu
  // entries true-centered, and the utility cluster at the end with the
  // search box as its elastic leading edge.
  .td-site-nav {
    display: grid;
    grid-template-columns: 1fr auto 1fr;
    align-items: center;
    column-gap: 16px;
    height: 100%;
  }

  .td-nav-brand {
    justify-self: start;
  }

  .td-nav-menu-zone {
    justify-self: center;
    min-width: 0;
  }

  .td-nav-util-zone {
    justify-self: end;
  }

  .td-nav-brand {
    display: flex;
    align-items: center;
    gap: 10px;
    color: var(--bs-body-color);

    &:hover {
      color: var(--bs-body-color);
      text-decoration: none;
    }
  }

  .td-nav-logo {
    display: block;
    width: 22px;
    height: 22px;
  }

  .td-nav-wordmark {
    display: block;
    width: auto;
    // The text half of the lockup: ~70% of the 22px mark beside it, not
    // sized to stand alone.
    height: 16px;
  }

  .td-nav-title {
    margin-inline-end: -0.14em;
    background: var(--td-brand-mark-gradient);
    background-clip: text;
    color: transparent;
    font-family: var(--td-display-font-family);
    font-size: 1.05rem;
    font-weight: 700;
    line-height: 1;
    letter-spacing: 0.14em;
    -webkit-background-clip: text;
    -webkit-text-fill-color: transparent;
  }

  .td-nav-links {
    display: flex;
    align-items: center;
    gap: 4px;
  }

  .nav-link {
    display: inline-flex;
    align-items: center;
    gap: 7px;
    padding: 6px 10px;
    border-radius: 8px;
    // One tone for every navbar control; hovering glides text and glyph to
    // the link color while the soft ground fades in, and the active item
    // darkens.
    color: var(--bs-tertiary-color);
    font-size: 14px;
    font-weight: 500;
    transition:
      background-color var(--td-motion-duration) var(--td-shell-ease-color),
      color var(--td-motion-duration) var(--td-shell-ease-color);

    // One tone for every entry at rest -- the top row is not where a
    // section's identity belongs. Hovering picks up the accent of the
    // section the reader is currently in.
    &:hover,
    &:focus-visible {
      background: var(--td-brand-elev);
      color: var(--td-accent-hover);
      text-decoration: none;
    }

    &.active {
      color: var(--bs-body-color);
    }
  }

  .td-nav-menu {
    position: relative;
    display: inline-flex;
  }

  .td-nav-menu.td-is-open .td-nav-menu__parent-link {
    background: var(--td-brand-elev);
    color: var(--td-accent-hover);
  }

  .td-nav-menu__panel {
    position: absolute;
    top: calc(100% + 8px);
    inset-inline-start: 0;
    z-index: 110;
    // One moderate single column: every row is an icon and a title.
    min-width: 230px;
    max-width: unquote('min(300px, calc(100vw - 32px))');
    padding: 7px;
    border: 1px solid var(--bs-border-color);
    border-radius: 10px;
    background: var(--bs-body-bg);
    box-shadow: var(--td-brand-shadow-md);

    // Invisible bridge over the gap below the label, so the pointer can
    // travel from the trigger into the panel without a dead zone.
    &::before {
      content: '';
      position: absolute;
      inset-inline: 0;
      top: -9px;
      height: 9px;
    }

    // The panel breathes in and out instead of popping: a fast fade with a
    // small settle, riding the shared hover curve. The runtime still toggles
    // only `hidden`; `allow-discrete` holds `display` until the exit fade
    // lands, and the `@starting-style` block at the end of this file gives
    // the entry its from-state. Browsers without discrete display transitions
    // fall back to today's instant toggle, and reduced motion zeroes the
    // duration tokens.
    opacity: 1;
    translate: 0 0;
    transition:
      opacity var(--td-motion-duration-fast) var(--td-shell-ease-color),
      translate var(--td-motion-duration-fast) var(--td-shell-ease-color),
      display var(--td-motion-duration-fast) allow-discrete;

    &[hidden] {
      display: none;
      opacity: 0;
      translate: 0 -4px;
    }
  }

  .td-nav-menu__panel--taxonomy {
    width: unquote('min(520px, calc(100vw - 32px))');
    max-width: none;
    padding: 10px;
  }

  .td-navbar-taxonomy-tags {
    display: flex;
    flex-wrap: wrap;
    align-items: flex-start;
    gap: 7px;
  }

  .td-navbar-taxonomy-tag {
    display: flex;
    align-items: center;
    flex: 0 1 auto;
    gap: 8px;
    max-width: 100%;
    min-width: 0;
    padding: 7px 8px 7px 10px;
    border: 1px solid var(--bs-border-color);
    border-radius: 999px;
    color: var(--bs-body-color);
    font-size: 0.8125rem;
    line-height: 1.2;
    transition:
      background-color var(--td-motion-duration) var(--td-shell-ease-color),
      border-color var(--td-motion-duration) var(--td-shell-ease-color),
      color var(--td-motion-duration) var(--td-shell-ease-color);

    &:hover,
    &:focus-visible {
      border-color: var(--bs-secondary-color);
      background: var(--td-brand-elev);
      color: var(--bs-link-hover-color);
      text-decoration: none;
    }
  }

  .td-navbar-taxonomy-tag__name {
    min-width: 0;
    overflow: hidden;
    text-overflow: ellipsis;
    white-space: nowrap;
  }

  .td-navbar-taxonomy-tag__count {
    display: inline-grid;
    place-items: center;
    min-width: 1.5rem;
    height: 1.5rem;
    flex: 0 0 auto;
    padding-inline: 0.35rem;
    border-radius: 999px;
    background: var(--bs-tertiary-bg);
    color: var(--bs-secondary-color);
    font-family: var(--td-meta-font-family);
    font-size: 0.6875rem;
    font-variant-numeric: tabular-nums;
  }

  .td-nav-menu__item-link,
  .td-nav-menu__group-title {
    display: flex;
    align-items: center;
    gap: 9px;
    padding: 8px 9px;
    border-radius: 7px;
    color: var(--bs-body-color);
    font-size: 0.875rem;
    font-weight: 500;
    transition:
      background-color var(--td-motion-duration) var(--td-shell-ease-color),
      color var(--td-motion-duration) var(--td-shell-ease-color);

    &:hover,
    &:focus-visible {
      background: var(--td-brand-elev);
      color: var(--td-accent-hover);
      text-decoration: none;

      > i {
        color: inherit;
      }
    }

    &.active {
      color: var(--bs-link-color);
    }

    > i {
      flex: 0 0 auto;
      width: 20px;
      color: var(--bs-tertiary-color);
      text-align: center;
      transition: color var(--td-motion-duration) var(--td-shell-ease-color);
    }

    > .td-navbar-entry__label {
      min-width: 0;
      overflow: hidden;
      text-overflow: ellipsis;
      white-space: nowrap;
    }
  }

  .td-nav-menu__group-title {
    margin-block-start: 3px;
    font-weight: 650;
  }

  .td-navbar-entry__external {
    display: inline-flex;
    color: var(--bs-tertiary-color);

    .td-shell-icon {
      --td-shell-icon-size: 13px;
    }
  }

  .td-navbar-group__items {
    margin-inline-start: 12px;
    padding-inline-start: 6px;
    border-inline-start: 1px solid var(--bs-border-color);
  }

  .td-nav-util {
    display: inline-flex;
    align-items: center;
    justify-content: center;
    min-width: 34px;
    height: 34px;
    margin-inline-start: 0;
    padding: 0 8px;
    border: 0;
    border-radius: 8px;
    background: transparent;
    color: var(--bs-tertiary-color);
    font-size: 1rem;
    cursor: pointer;
    transition:
      background-color var(--td-motion-duration) var(--td-shell-ease-color),
      color var(--td-motion-duration) var(--td-shell-ease-color);

    &:hover,
    &:focus-visible {
      background: var(--td-brand-elev);
      color: var(--bs-link-hover-color);
      text-decoration: none;
    }
  }

  .td-nav-util .td-shell-icon,
  .td-nav-github .td-shell-icon {
    --td-shell-icon-size: 18px;
  }

  // Boxed search trigger: reads as a short input advertising the "/" shortcut,
  // opens the Command Palette like the icon it replaces. Collapses back to an
  // icon in the compact state.
  .td-nav-search-box {
    display: inline-flex;
    align-items: center;
    gap: 8px;
    width: 190px;
    height: 34px;
    margin-inline-end: 4px;
    padding: 0 8px 0 10px;
    border: 1px solid var(--bs-border-color);
    border-radius: 8px;
    background: transparent;
    color: var(--bs-tertiary-color);
    font-size: 13px;
    cursor: pointer;
    transition:
      background-color var(--td-motion-duration) var(--td-shell-ease-color),
      border-color var(--td-motion-duration) var(--td-shell-ease-color),
      color var(--td-motion-duration) var(--td-shell-ease-color);

    &:hover,
    &:focus-visible {
      border-color: var(--bs-secondary-color);
      background: var(--td-brand-elev);
      color: var(--bs-link-hover-color);
    }

    .td-shell-icon {
      flex: none;
      --td-shell-icon-size: 14px;
    }
  }

  .td-nav-search-box__hint {
    flex: 1 1 auto;
    min-width: 0;
    overflow: hidden;
    text-align: start;
    text-overflow: ellipsis;
    white-space: nowrap;
  }

  .td-nav-search-box__kbd {
    flex: none;
    min-width: 18px;
    padding: 0 5px;
    border: 1px solid var(--bs-border-color);
    border-radius: 5px;
    background: var(--bs-body-bg);
    box-shadow: none;
    color: var(--bs-tertiary-color);
    font-family: var(--td-code-font-family);
    font-size: 11px;
    line-height: 17px;
    text-align: center;
  }

  .td-nav-github {
    display: inline-flex;
    align-items: center;
    gap: 5px;
    margin-inline-start: 0;
    padding: 6px 8px;
    border-radius: 8px;
    color: var(--bs-tertiary-color);
    font-size: 1rem;
    transition:
      background-color var(--td-motion-duration) var(--td-shell-ease-color),
      color var(--td-motion-duration) var(--td-shell-ease-color);

    &:hover,
    &:focus-visible {
      background: var(--td-brand-elev);
      color: var(--bs-link-hover-color);
      text-decoration: none;
    }
  }

  // Text that sits beside a utility icon (star count, alt-site label) uses
  // the same size and weight as the menu labels, not the 1rem icon box.
  .td-nav-github .td-nav-count,
  .td-nav-alt-site > span {
    font-size: 14px;
    font-weight: 500;
    font-variant-numeric: tabular-nums;
  }

  .td-site-nav__language.td-language-selector--menu {
    padding: 0;

    > .td-language-selector__trigger {
      width: 34px;
      height: 34px;
      min-width: 34px;
      min-height: 34px;
      padding: 0;

      > span {
        display: none;
      }
    }
  }

}

// Matches the .td-site-header .td-nav-util specificity from later in the
// cascade, so the shared utility display cannot resurface this entry outside
// its below-md tier.
.td-site-header .td-site-drawer-toggle {
  display: none;
}

// Icon + label link (single-language sites); the label needs the same
// breathing room after its icon as the GitHub star count.
.td-site-header .td-nav-alt-site {
  gap: 6px;
  white-space: nowrap;
}

// The desktop shell sidebar deliberately masks the navbar's start edge and
// already provides its own Home link. Keep the covered duplicate out of the
// keyboard focus order; it returns when the sidebar is collapsed or becomes a
// mobile drawer.
@media (min-width: 768px) {
  html:not([data-td-shell-sidebar='collapsed'])
    body.td-shell-chrome--navbar:has(#td-shell-sidebar)
    .td-site-header
    .td-nav-brand {
    visibility: hidden;
  }
}

.td-site-drawer {
  position: fixed;
  inset: $td-navbar-min-height 0 auto;
  z-index: 99;
  max-height: calc(100dvh - #{$td-navbar-min-height});
  overflow-y: auto;
  padding: 12px 14px 20px;
  border-bottom: 1px solid var(--bs-border-color);
  background: var(--bs-body-bg);
  box-shadow: var(--td-brand-shadow-md);

  &[hidden] {
    display: none;
  }

  nav {
    display: grid;
    max-width: 720px;
    margin: 0 auto;
  }

  // One row vocabulary with the docs drawer tree: quiet 14px rows, a soft
  // hover pill, and the primary-dim treatment for the active entry.
  .td-site-nav__menu-link {
    display: flex;
    align-items: center;
    gap: 8px;
    min-height: 40px;
    padding: 8px 10px;
    border: 0;
    border-radius: 10px;
    background: transparent;
    color: var(--td-shell-muted-fg);
    font-size: 14px;
    font-weight: 400;
    text-align: start;
    text-decoration: none;
    transition: background-color var(--td-motion-duration) ease;

    &:hover,
    &:focus-visible {
      background: var(--td-shell-accent);
      color: var(--bs-body-color);
      transition: none;
    }

    &.active {
      background: var(--td-shell-primary-dim);
      color: var(--td-shell-primary);
    }

    // Row glyphs sit one step below the label size on one shared column,
    // for both Font Awesome markers and the shell's SVG icons.
    > i {
      flex: 0 0 auto;
      width: 18px;
      color: var(--bs-tertiary-color);
      font-size: 14px;
      text-align: center;
    }

    .td-shell-icon {
      flex: 0 0 auto;
      --td-shell-icon-size: 15px;
      color: var(--bs-tertiary-color);
    }
  }

  .td-site-nav__menu-link--button {
    width: 100%;
  }

  &__children {
    padding-inline-start: 18px;
  }
}

// Wordmark sites keep a plain logo in reserve for the compact state.
// One popover look everywhere: the language selector ships its own pop
// styles for the sidebar, so realign the navbar copy with .td-nav-hover-menu.
.td-site-header .td-site-nav__language {
  .td-language-selector__trigger {
    color: var(--bs-tertiary-color);
    transition:
      background-color var(--td-motion-duration) var(--td-shell-ease-color),
      color var(--td-motion-duration) var(--td-shell-ease-color);

    &:hover,
    &:focus-visible {
      background: var(--td-brand-elev);
      color: var(--bs-link-hover-color);
    }
  }

  > ul {
    min-width: 10rem;
    padding: 7px;
    border: 1px solid var(--bs-border-color);
    border-radius: 10px;
    background: var(--bs-body-bg);
    box-shadow: var(--td-brand-shadow-md);
  }
}

// Shared hover popover for the utility controls (theme, version): the trigger
// keeps its own click action, hovering or focusing reveals the options. One
// look for every navbar popover — same border, radius, shadow, and padding as
// .td-nav-menu__panel.
.td-nav-hover-menu {
  position: relative;
  display: inline-flex;

  &__pop {
    position: absolute;
    top: calc(100% + 8px);
    inset-inline-end: 0;
    z-index: 110;
    display: none;
    flex-direction: column;
    gap: 2px;
    min-width: 10rem;
    padding: 7px;
    border: 1px solid var(--bs-border-color);
    border-radius: 10px;
    background: var(--bs-body-bg);
    box-shadow: var(--td-brand-shadow-md);

    // Same dead-zone bridge as the nav menus.
    &::before {
      content: '';
      position: absolute;
      inset-inline: 0;
      top: -9px;
      height: 9px;
    }
  }

  &.td-is-open &__pop {
    display: flex;
  }

  &__option {
    display: flex;
    align-items: center;
    gap: 8px;
    padding: 7px 9px;
    border: 0;
    border-radius: 7px;
    background: transparent;
    color: var(--bs-body-color);
    font-size: 13px;
    font-weight: 400;
    text-align: start;
    text-decoration: none;
    cursor: pointer;
    transition:
      background-color var(--td-motion-duration) var(--td-shell-ease-color),
      color var(--td-motion-duration) var(--td-shell-ease-color);

    &:hover,
    &:focus-visible {
      background: var(--td-brand-elev);
      color: var(--bs-link-hover-color);
      text-decoration: none;
    }

    &[aria-pressed='true'],
    &.td-is-active {
      color: var(--bs-link-color);
    }

    &.td-is-disabled {
      color: var(--bs-tertiary-color);
      cursor: default;
    }

    > i {
      width: 15px;
      color: var(--bs-tertiary-color);
      font-size: 13px;
      text-align: center;
    }
  }

  &__divider {
    margin: 4px 2px;
    border: 0;
    border-top: 1px solid var(--bs-border-color);
    opacity: 1;
  }
}

// Between lg and the widest layouts the centered menu leaves less room for
// the side zones; the search box gives up some of its width first.
@media (max-width: 1199.98px) {
  .td-site-header .td-nav-search-box {
    width: 150px;
  }
}

// Compact state: below lg every fixed-count control drops its text so the row
// always fits, right-aligned — logo only, icon-only menu items, and icon
// triggers for search, language, theme, version, and GitHub. This is the only
// other navbar state; phones use it too.
@media (max-width: 991.98px) {
  .td-site-header {
    // The three-zone grid stays: the menu keeps its icons true-centered
    // between the brand and the utility cluster at every compact width.
    .td-site-nav {
      grid-template-columns: minmax(0, 1fr) auto minmax(0, 1fr);
    }

    // The search box collapses to the plain icon trigger it replaced.
    .td-nav-search-box {
      width: auto;
      min-width: 34px;
      justify-content: center;
      margin-inline-end: 0;
      padding: 0 8px;
      border-color: transparent;

      &:hover,
      &:focus-visible {
        border-color: transparent;
      }

      .td-shell-icon {
        --td-shell-icon-size: 18px;
      }
    }

    .td-nav-search-box__hint,
    .td-nav-search-box__kbd {
      display: none;
    }

    .td-nav-title,
    .td-nav-wordmark {
      display: none;
    }

    .td-nav-alt-site > span,
    .td-nav-github .td-nav-count {
      display: none;
    }

    .td-nav-links > .nav-link .td-navbar-entry__label,
    .td-nav-links > .nav-link .td-navbar-entry__external,
    .td-nav-menu > .td-nav-menu__parent-link .td-navbar-entry__label,
    .td-nav-menu > .td-nav-menu__parent-link .td-navbar-entry__external {
      display: none;
    }

    .nav-link {
      min-width: 34px;
      min-height: 34px;
      justify-content: center;
      padding: 6px 8px;
      font-size: 1rem;
    }

    // Taxonomy clouds can be much wider than their icon trigger. Anchor the
    // compact panel to the viewport instead of letting it overflow from the
    // rightmost menu item.
    .td-nav-menu__panel--taxonomy {
      position: fixed;
      inset-block-start: $td-navbar-min-height;
      inset-inline: 16px;
      width: auto;
    }
  }
}

// Give the remaining phone controls a little more horizontal breathing room
// on truly narrow screens without shrinking their hit area.
@media (max-width: 479.98px) {
  .td-shell-chrome .td-site-header .td-site-container {
    padding-inline: 10px;
  }

  .td-site-header {
    .td-nav-links {
      gap: 2px;
    }

    .nav-link,
    .td-nav-util,
    .td-nav-github,
    .td-nav-search-box,
    .td-site-nav__language.td-language-selector--menu
      > .td-language-selector__trigger {
      flex: 0 0 28px;
      width: 28px;
      min-width: 28px;
      height: 34px;
      min-height: 34px;
      justify-content: center;
      padding: 0;
    }
  }
}

// Shell drawer opener; shown below md only (the drawer only exists there).
.td-site-header .td-site-nav__menu-toggle.td-nav-util {
  display: none;
}

.td-default {
  main > section:first-of-type {
    @include media-breakpoint-up(md) {
      padding-top: $td-block-space-top-base;
    }
  }

}

// Below md the shell sidebar becomes a drawer; its toggle joins the icon row.
@media (max-width: 767.98px) {
  // Keep the content-generated menu on the physical center line. Equal outer
  // tracks mean the larger search/menu cluster on the end edge cannot push
  // these links to the right.
  .td-site-header .td-site-nav {
    display: grid;
    grid-template-columns: minmax(0, 1fr) auto minmax(0, 1fr);
    column-gap: 4px;
  }

  .td-site-header .td-nav-brand {
    justify-self: start;
  }

  .td-site-header .td-nav-menu-zone {
    justify-self: center;
  }

  .td-site-header .td-nav-util-zone {
    justify-self: end;
  }

  // Phone chrome has one deliberately small right-hand contract: search and
  // the relevant drawer/menu opener. Version, language, theme, and GitHub
  // remain available in the drawer footer instead of competing for this row.
  .td-site-header .td-nav-util-zone {
    > .td-nav-version-menu,
    > .td-site-nav__language,
    > .td-nav-alt-site,
    > .td-nav-theme-menu,
    > .td-nav-github {
      display: none;
    }
  }

  .td-site-header .td-site-nav__menu-toggle.td-nav-util {
    display: inline-flex;
  }

  // Home and Landing have no sidebar drawer; in the same slot and tier their
  // opener reveals the site drawer with the full labelled tree instead.
  .td-site-header .td-site-drawer-toggle {
    display: inline-flex;
  }

  .td-site-container {
    padding: 0 14px;
  }
}

// The H-key reading mode hides the navbar with the rest
// of the chrome; fixed elements and anchor jumps stop reserving its height.
html[data-td-kbd-zen] .td-site-header {
  display: none;
}

html[data-td-kbd-zen] .td-navbar-autohide {
  display: none;
}

html[data-td-kbd-zen]:has(body.td-shell-chrome--navbar) {
  --td-shell-nav-h: 0px;
  scroll-padding-top: 1.5rem;
}

// The drawer-width tier is the final authority: even a persisted keyboard zen
// state must not remove the only always-visible global navigation surface.
@media (max-width: 767.98px) {
  html[data-td-kbd-zen] .td-navbar-autohide {
    display: contents;
  }

  html[data-td-kbd-zen] .td-site-header {
    display: block;
  }

  html[data-td-kbd-zen]:has(body.td-shell-chrome--navbar) {
    --td-shell-nav-h: #{$td-navbar-min-height};
    scroll-padding-top: calc(var(--td-shell-nav-h) + 1.5rem);
  }
}

@media (forced-colors: active) {
  .td-site-header .td-nav-title {
    color: CanvasText;
    -webkit-text-fill-color: CanvasText;
  }
}

@media (prefers-reduced-motion: reduce) {
  .td-navbar-autohide > .td-site-header {
    transition: none;
  }
}

@media print {
  .td-site-header .td-nav-title {
    color: #1d588c;
    -webkit-text-fill-color: #1d588c;
  }
}

// Entry from-state for the navbar panels' discrete display transition: the
// frame a panel un-hides, it starts faded and lifted, then glides to rest.
// Top level rather than nested so the emitted at-rule survives LibSass.
@starting-style {
  .td-site-header .td-nav-menu__panel {
    opacity: 0;
    translate: 0 -4px;
  }
}
